#!/usr/bin/env python3
"""Minimal PDF text extraction: inflate streams, collect Tj/TJ text."""
import re
import sys
import zlib


def extract(path: str) -> str:
    data = open(path, "rb").read()
    chunks = []
    for m in re.finditer(rb"stream\r?\n", data):
        start = m.end()
        end = data.find(b"endstream", start)
        if end < 0:
            continue
        raw = data[start:end]
        try:
            text = zlib.decompress(raw)
        except Exception:
            continue
        chunks.append(text)
    out = []
    for chunk in chunks:
        # text show operators: (..) Tj and [ (a) -10 (b) ] TJ
        for m in re.finditer(rb"\[(.*?)\]\s*TJ", chunk, re.S):
            seg = b""
            for sm in re.finditer(rb"\((?:\\.|[^\\()])*\)", m.group(1)):
                seg += sm.group(0)[1:-1]
            out.append(seg)
        for m in re.finditer(rb"\((?:\\.|[^\\()])*\)\s*Tj", chunk, re.S):
            out.append(m.group(0)[m.group(0).find(b"(") + 1 : m.group(0).rfind(b")")])
        for m in re.finditer(rb"\((?:\\.|[^\\()])*\)\s*'", chunk, re.S):
            out.append(m.group(0)[1 : m.group(0).rfind(b")")])
    body = b"\n".join(out)
    body = body.replace(b"\\(", b"(").replace(b"\\)", b")").replace(b"\\\\", b"\\")
    return body.decode("latin-1", "replace")


if __name__ == "__main__":
    print(extract(sys.argv[1]))

